+    border-radius: 4px;
+    font-size: 0.9rem;
+}
+
+::deep .toast-success {
+    background: #d1e7dd;
+    color: #0f5132;
+    border: 1px solid #badbcc;
+}
+
+::deep .error-message {
+    color: #dc3545;
+    font-size: 0.85rem;
+    margin: 0.5rem 0;
+}
+
+::deep .success-message {
+    color: #198754;
+    font-size: 0.85rem;
+    margin: 0.5rem 0;
+}
+
