+::deep .avatar-preview {
+    margin-bottom: 1.5rem;
+    text-align: center;
+}
+
+::deep .avatar-image {
+    width: 96px;
+    height: 96px;
+    border-radius: 50%;
+    object-fit: cover;
+    border: 2px solid #dee2e6;
