+
+::deep .avatar-url {
+    margin-top: 0.5rem;
+    font-size: 0.8rem;
+    color: #6c757d;
+    word-break: break-all;
+}
+
+/* Toggles */
+::deep .toggle-group {
+    display: flex;
+    flex-direction: column;
+    gap: 0.75rem;
+}
+
+::deep .toggle-item {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    cursor: pointer;
+}
+
+::deep .toggle-item input[type="checkbox"] {
+    width: 18px;
+    height: 18px;
+}
+
+/* Channels */
+::deep .channel-list {
+    display: flex;
+    flex-direction: column;
+    gap: 0.5rem;
+}
+
+::deep .channel-item {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    cursor: pointer;
+}
+
+/* Security */
+::deep .expandable-panel {
+    border: 1px solid #dee2e6;
+    border-radius: 4px;
+    margin-bottom: 1.5rem;
+}
+
+::deep .panel-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    width: 100%;
+    padding: 0.75rem 1rem;
+    background: #f8f9fa;
+    border: none;
+    cursor: pointer;
+    font-size: 1rem;
+    font-weight: 500;
+}
+
+::deep .panel-header:hover {
+    background: #e9ecef;
+}
+
+::deep .panel-body {
+    padding: 1rem;
+    border-top: 1px solid #dee2e6;
+}
+
+::deep .twofa-section {
+    margin-bottom: 1.5rem;
+}
+
+::deep .twofa-status {
+    display: flex;
+    align-items: center;
+    gap: 0.75rem;
+}
+
+::deep .status-indicator {
+    width: 10px;
+    height: 10px;
+    border-radius: 50%;
+}
+
+::deep .status-enabled {
+    background: #198754;
+}
+
+::deep .status-disabled {
+    background: #dc3545;
+}
+
+::deep .info-text {
+    font-size: 0.85rem;
+    color: #6c757d;
+    margin-top: 0.5rem;
+}
+
+::deep .sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    margin-top: 0.5rem;
+}
+
+::deep .sessions-table th,
+::deep .sessions-table td {
+    padding: 0.5rem 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #dee2e6;
+}
+
+::deep .sessions-table th {
+    background: #f8f9fa;
+    font-weight: 600;
+    font-size: 0.85rem;
+    color: #495057;
+}
+
+::deep .current-badge {
+    font-size: 0.75rem;
+    background: #e7f1ff;
+    color: #0d6efd;
+    padding: 0.2rem 0.5rem;
+    border-radius: 3px;
+}
+
+/* Modal */
+::deep .modal-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+::deep .modal-dialog {
+    background: white;
+    padding: 1.5rem;
+    border-radius: 8px;
+    max-width: 400px;
+    width: 90%;
+}
+
+::deep .modal-dialog h4 {
+    margin-top: 0;
+}
+
+::deep .modal-actions {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 1rem;
+}
+
+/* Appearance */
+::deep .radio-group {
+    display: flex;
+    gap: 1.5rem;
+    margin-top: 0.25rem;
+}
+
+::deep .radio-item {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+}
+
+::deep .live-preview {
+    margin-top: 1.5rem;
+    padding: 1.5rem;
+    border: 1px solid #dee2e6;
+    border-radius: 8px;
+}
+
+::deep .live-preview h4 {
+    margin-top: 0;
+    margin-bottom: 0.75rem;
+}
+
+::deep .preview-card {
+    background: #f8f9fa;
+    padding: 1rem;
