+    display: flex;
+    flex-direction: column;
+    gap: 0.25rem;
+}
+
+::deep .preview-title {
+    font-weight: 600;
+}
+
+/* Preview theme variations */
+::deep .preview-dark {
+    background: #212529;
+    color: #f8f9fa;
+    border-color: #495057;
+}
+
+::deep .preview-dark .preview-card {
+    background: #343a40;
+}
+
+::deep .preview-light {
+    background: #ffffff;
+    color: #212529;
+}
+
+::deep .preview-system {
+    background: #f0f0f0;
+    color: #333;
+}
+
+/* Preview font sizes */
+::deep .preview-font-small {
+    font-size: 0.85rem;
+}
+
+::deep .preview-font-medium {
+    font-size: 1rem;
+}
+
+::deep .preview-font-large {
+    font-size: 1.15rem;
+}
+
+/* Compact mode */
+::deep .compact {
+    padding: 0.75rem;
+}
+
+::deep .compact .preview-card {
+    padding: 0.5rem;
+}
